# Try: fill 1s with column dominant color
from collections import Counter

output_grid = []
for i, row in enumerate(input_grid):
    new_row = []
    for j, cell in enumerate(row):
        if cell == 1:
            # Find dominant color in this column (excluding 1s)
            col_colors = [input_grid[r][j] for r in range(len(input_grid)) if input_grid[r][j] != 1]
            if col_colors:
                counts = Counter(col_colors)
                dominant = counts.most_common(1)[0][0]
                new_row.append(dominant)
            else:
                new_row.append(0)
        else:
            new_row.append(cell)
    output_grid.append(new_row)

print("Column-based fill")
print(output_grid[:6])
